import { expect, expectStatus, test } from "../../fixtures";

interface VendorPage {
  items: unknown[];
  total: number;
  limit: number;
  offset: number;
}

test.describe("vendor list paging", () => {
  test(
    "a page past the last vendor is empty but still reports the total",
    { tag: "@LIF-15" },
    async ({ apiAs, factory }) => {
      // Arrange: make sure the tenant has at least one vendor, then read the first page's total.
      await factory.vendor({ as: "member" });
      const member = await apiAs("member");
      const first = await expectStatus<VendorPage>(await member.get("/api/vendors"), 200);
      expect(first.total).toBeGreaterThan(0);

      // Act: ask for a page that starts beyond every vendor in the tenant.
      const offset = first.total + 1000;
      const response = await member.get("/api/vendors", { params: { offset, limit: 20 } });

      // Assert
      const past = await expectStatus<VendorPage>(response, 200);
      expect(past.items).toEqual([]);
      expect(past.total).toBe(first.total);
      expect(past.offset).toBe(offset);
    },
  );
});
